  const isSubmit = (m, u) => /^post$/i.test(m || "") && /^https:\/\/vps\.kodub\.com\/(.*\/)?leaderboard(\?|$)/.test(String(u));
  const XO = XMLHttpRequest.prototype.open, XS = XMLHttpRequest.prototype.send;
